Here is the commit message:
net: skbuff: preserve shared-frag marker during coalescing

skb_try_coalesce() can attach paged frags from @from to @to.  If @from
has SKBFL_SHARED_FRAG set, the resulting @to skb can contain the same
externally-owned or page-cache-backed frags, but the shared-frag marker
is currently lost.

That breaks the invariant relied on by later in-place writers.  In
particular, ESP input checks skb_has_shared_frag() before deciding
whether an uncloned nonlinear skb can skip skb_cow_data().  If TCP
receive coalescing has moved shared frags into an unmarked skb, ESP can
see skb_has_shared_frag() as false and decrypt in place over page-cache
backed frags.

Propagate SKBFL_SHARED_FRAG when skb_try_coalesce() transfers paged
frags.  The tailroom copy path does not need the marker because it copies
bytes into @to's linear data rather than transferring frag descriptors.

Fixes: cef401de7be8 ("net: fix possible wrong checksum generation")
Fixes: f4c50a4034e6 ("xfrm: esp: avoid in-place decrypt on shared skb frags")
Signed-off-by: William Bowling <vakzz@zellic.io>
Reviewed-by: Eric Dumazet <edumazet@google.com>
Tested-by: Jiayuan Chen <jiayuan.chen@linux.dev>
Link: https://patch.msgid.link/20260513041635.1289541-1-vakzz@zellic.io
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In `skb_try_coalesce()`, when paged fragments are transferred from the `from` skb to the `to` skb, the `SKBFL_SHARED_FRAG` flag from `from_shinfo->flags` is not propagated to `to_shinfo->flags`. This breaks the invariant that any skb containing externally-owned or page-cache-backed frags must have the shared-frag marker set. Consequently, downstream code (e.g., ESP input) that checks `skb_has_shared_frag()` may see it as false and perform in-place decryption on shared fragments, leading to data corruption.

Here is the patch:
  */
 bool skb_try_coalesce(struct sk_buff *to, struct sk_buff *from,
 		      bool *fragstolen, int *delta_truesize)
 {
 	struct skb_shared_info *to_shinfo, *from_shinfo;
 	int i, delta, len = from->len;

 	*fragstolen = false;

 	if (skb_cloned(to))
 		return false;

 	/* In general, avoid mixing page_pool and non-page_pool allocated
 	 * pages within the same SKB. In theory we could take full
 	 * references if @from is cloned and !@to->pp_recycle but its
 	 * tricky (due to potential race with the clone disappearing) and
 	 * rare, so not worth dealing with.
 	 */
 	if (to->pp_recycle != from->pp_recycle)
 		return false;

 	if (skb_frags_readable(from) != skb_frags_readable(to))
 		return false;

 	if (len <= skb_tailroom(to) && skb_frags_readable(from)) {
 		if (len)
 			BUG_ON(skb_copy_bits(from, 0, skb_put(to, len), len));
 		*delta_truesize = 0;
 		return true;
 	}

 	to_shinfo = skb_shinfo(to);
 	from_shinfo = skb_shinfo(from);
 	if (to_shinfo->frag_list || from_shinfo->frag_list)
 		return false;
 	if (skb_zcopy(to) || skb_zcopy(from))
 		return false;

 	if (skb_headlen(from) != 0) {
 		struct page *page;
 		unsigned int offset;

 		if (to_shinfo->nr_frags +
 		    from_shinfo->nr_frags >= MAX_SKB_FRAGS)
 			return false;

 		if (skb_head_is_locked(from))
 			return false;

 		delta = from->truesize - SKB_DATA_ALIGN(sizeof(struct sk_buff));

 		page = virt_to_head_page(from->head);
 		offset = from->data - (unsigned char *)page_address(page);

 		skb_fill_page_desc(to, to_shinfo->nr_frags,
 				   page, offset, skb_headlen(from));
 		*fragstolen = true;
 	} else {
 		if (to_shinfo->nr_frags +
 		    from_shinfo->nr_frags > MAX_SKB_FRAGS)
 			return false;

 		delta = from->truesize - SKB_TRUESIZE(skb_end_offset(from));
 	}

 	WARN_ON_ONCE(delta < len);

 	memcpy(to_shinfo->frags + to_shinfo->nr_frags,
 	       from_shinfo->frags,
 	       from_shinfo->nr_frags * sizeof(skb_frag_t));
 	to_shinfo->nr_frags += from_shinfo->nr_frags;
+	if (from_shinfo->nr_frags)
+		to_shinfo->flags |= from_shinfo->flags & SKBFL_SHARED_FRAG;

 	if (!skb_cloned(from))
 		from_shinfo->nr_frags = 0;

 	/* if the skb is not cloned this does nothing
 	 * since we set nr_frags to 0.
 	 */
 	if (skb_pp_frag_ref(from)) {
 		for (i = 0; i < from_shinfo->nr_frags; i++)
 			__skb_frag_ref(&from_shinfo->frags[i]);
 	}

 	to->truesize += delta;
 	to->len += len;
 	to->data_len += len;

 	*delta_truesize = delta;
 	return true;
 }
 EXPORT_SYMBOL(skb_try_coalesce);


